// Today's bounds in the workflow timezone (America/El_Salvador, UTC-6, no DST).
// $now is a Luxon DateTime in the workflow timezone.
const dayStart = $now.startOf('day');
const dayEnd = dayStart.plus({ days: 1 }).minus({ milliseconds: 1 });

const todayLabel = new Intl.DateTimeFormat('es-SV', {
  timeZone: 'America/El_Salvador',
  weekday: 'long',
  day: 'numeric',
  month: 'long',
  year: 'numeric',
}).format(new Date($now.toMillis()));

return [{ json: { dayStartISO: dayStart.toISO(), dayEndISO: dayEnd.toISO(), todayLabel } }];

// Compose the morning briefing email from the three source nodes.
// Every fetcher continues on error, so guard every lookup defensively.

const weather = (() => {
  try {
    const item = $('Fetch Weather').item.json;
    return item && item.current ? item.current : null;
  } catch (e) {
    return null;
  }
})();

const events = (() => {
  try {
    return $('Fetch Calendar').all().map((i) => i.json);
  } catch (e) {
    return null;
  }
})();

const tasks = (() => {
  try {
    return $('Fetch Tasks').all().map((i) => i.json);
  } catch (e) {
    return null;
  }
})();

// WMO weather code -> Spanish label
const WEATHER_LABELS = {
  0: 'Cielo despejado',
  1: 'Mayormente despejado',
  2: 'Parcialmente nublado',
  3: 'Nublado',
  45: 'Niebla',
  48: 'Niebla con escarcha',
  51: 'Llovizna ligera',
  52: 'Llovizna',
  53: 'Llovizna moderada',
  55: 'Llovizna densa',
  56: 'Llovizna helada ligera',
  57: 'Llovizna helada',
  61: 'Lluvia ligera',
  63: 'Lluvia moderada',
  65: 'Lluvia fuerte',
  66: 'Lluvia helada ligera',
  67: 'Lluvia helada',
  71: 'Nieve ligera',
  73: 'Nieve moderada',
  75: 'Nieve fuerte',
  77: 'Cristales de nieve',
  80: 'Chubascos ligeros',
  81: 'Chubascos',
  82: 'Chubascos fuertes',
  85: 'Chubascos de nieve ligera',
  86: 'Chubascos de nieve',
  95: 'Tormenta',
  96: 'Tormenta con granizo',
  99: 'Tormenta con granizo fuerte',
};

const weatherLabel = weather && weather.weather_code !== undefined
  ? WEATHER_LABELS[weather.weather_code] || 'Desconocido'
  : 'No disponible';

const weatherLine = weather
  ? `${weatherLabel}, ${Math.round(weather.temperature_2m)}C (sensacion ${Math.round(weather.apparent_temperature)}C), humedad ${weather.relative_humidity_2m}%, viento ${weather.wind_speed_10m} km/h`
  : 'No disponible';

const eventLines = events && events.length
  ? events
      .slice()
      .sort((a, b) => String(a.start && (a.start.dateTime || a.start.date)).localeCompare(String(b.start && (b.start.dateTime || b.start.date))))
      .map((e) => {
        const start = e.start || {};
        const when = start.dateTime ? start.dateTime.slice(11, 16) : 'Todo el dia';
        return `- ${when}  ${e.summary || 'Sin titulo'}`;
      })
  : ['- Sin eventos para hoy'];

const taskLines = tasks && tasks.length
  ? tasks
      .slice()
      .sort((a, b) => String(a.due || '').localeCompare(String(b.due || '')))
      .map((t) => `- [ ] ${t.title} (${t.due ? t.due.slice(0, 10) : 'sin fecha'})`)
  : ['- Sin tareas pendientes'];

const subject = `Resumen matutino - ${$('Day Bounds').item.json.todayLabel}`;
const text = [
  'Buenos dias!',
  '',
  'CLIMA (San Salvador)',
  weatherLine,
  '',
  'EVENTOS DE HOY',
  ...eventLines,
  '',
  'TAREAS PENDIENTES',
  ...taskLines,
].join('\n');

return [{ json: { subject, text } }];
